vars_url = f'https://storage.googleapis.com/kenya-forecasting-data/{TARGET_DATE}/data/ECMWF_s2s_daily_vars_{TARGET_DATE}.zarr'

# Check if files exist via HEAD requests
try:
    precip_response = requests.head(precip_url, allow_redirects=True)
    vars_response = requests.head(vars_url, allow_redirects=True)
    if precip_response.status_code == 200 and vars_response.status_code == 200:
        print(f'Precipitation file accessible: {precip_url}')
        print(f'Variables file accessible: {vars_url}')
    else:
        raise Exception(f'Files not accessible: Precipitation {precip_response.status_code}, Variables {vars_response.status_code}')
except Exception as e:
    print(f'Error verifying files: {e}')

# List available files from the public listing URL
public_list_url = 'https://storage.googleapis.com/storage/v1/b/kenya-forecasting-data/o?prefix=2026-09-27/data/&delimiter='

try:
    public_list_response = requests.get(public_list_url)
    if public_list_response.status_code == 200:
        data = public_list_response.json()
        prefixes = data.get('prefixes', [])
        print(f'Available files in the archive: {prefixes}')
        expected_files = ['ECMWF_s2s_precip_2026-09-27.zarr', 'ECMWF_s2s_daily_vars_2026-09-27.zarr']
        for file in expected_files:
            if file in prefixes:
                print(f'Found expected file: {file}')
            else:
                print(f'Expected file not found: {file}')
    else:
        print(f'Failed to list files: HTTP {public_list_response.status_code}')

# Download precipitation data if available
if os.path.exists('/work/precip_data.zarr') is False:
    try:
        with requests.get(precip_url, stream=True) as r:
